"""Curated elemental Al gap fixes. Products are transcribed, not predicted."""
from pathlib import Path
import datetime,json,re
ROOT=Path(__file__).resolve().parents[2]
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
SOURCE_REVIEWED_AT='2026-11-20T03:25:18.814882+00:00'
elements=json.loads((ROOT/'public/data/explorer.json').read_text())['elements']
substances=[];sources=[];reactions=[]
subscript=str.maketrans('0123456789','₀₁₂₃₄₅₆₇₈₉')
def species(formula,state,name):
 found=next((s for s in substances if s['formula']==formula.translate(subscript) and s['state']==state),None)
 if found:return found['id']
 comp={symbol:int(count or 1) for symbol,count in re.findall(r'([A-Z][a-z]?)(\d*)',formula)}
 s={'id':'al-audit-'+formula+'-'+state,'name':name,'formula':formula.translate(subscript),'state':state,'composition':comp,'charge':0}
 if len(comp)==1:s['elementZ']=next(e['z'] for e in elements if e['symbol']==next(iter(comp)))
 substances.append(s);return s['id']
def source(id,name,url,edition=None):
 sources.append({'id':id,'name':name,'url':url,'retrievedAt':SOURCE_REVIEWED_AT,'upstreamDate':edition,'attribution':'Factual equations and original teaching summaries only. Source pages, images and experimental procedures are not redistributed.'});return id
we=source('al-we','WebElements: aluminium chemistry','https://www.webelements.com/aluminium/chemistry.html')
ttu=source('al-ttu','Texas Tech University: Chemical Equations, chapter 8','https://www.depts.ttu.edu/chemistry/faculty/jones/chapter_8.pdf')
book=source('al-grade11','Chemistry Grade 11 textbook: aluminium direct combinations, printed page 72','https://edu4mm.com/wp-content/uploads/2025/02/G11-Chemistry-new-course-TB-compressed.pdf')
nitride=source('al-nitride-primary','Materials 2019: direct thermal nitridation of aluminium','https://www.mdpi.com/1996-1944/12/3/359','2019')
epa=source('al-epa','US EPA chemical advisory: aluminium and sulfur reactivity','https://ncsp.tamu.edu/reports/EPA/lodirecc.htm')
carbide=source('al-carbide-primary','Kennedy, Drysdale and Gregory: elemental synthesis of Al4C3','https://eprints.gla.ac.uk/101625/','2015')
iodine=source('al-iodine-rsc','RSC / Nuffield: aluminium and iodine','https://edu.rsc.org/experiments/reacting-aluminium-and-iodine/715.article')
fluorine=source('al-fluorine-ocr','OCR: Atoms, bonds and groups — aluminium with fluorine','https://www.ocr.org.uk/Images/562880-question-paper-atoms-bonds-and-groups.pdf','2015')
Al=species('Al','s','Aluminum');O=species('O2','g','Oxygen');N=species('N2','g','Nitrogen');C=species('C','s','Carbon (graphitic solid)');S=species('S8','s','Sulfur (S₈)');Cl=species('Cl2','g','Chlorine');Br=species('Br2','l','Bromine');I=species('I2','s','Iodine');F=species('F2','g','Fluorine')
oxide=species('Al2O3','s','Aluminum oxide');nit=species('AlN','s','Aluminum nitride');sulf=species('Al2S3','s','Aluminum sulfide');car=species('Al4C3','s','Aluminum carbide');chloride=species('AlCl3','s','Aluminum chloride');bromide=species('Al2Br6','s','Aluminum bromide (dimer)');iodide=species('Al2I6','s','Aluminum iodide (dimer)');fluoride=species('AlF3','s','Aluminum fluoride')
def add(id,title,reactants,products,activation,label,source_ids,effects,observations,explanation,equation_only=False):
 r={'id':id,'title':title,'reactants':[{'id':s,'coefficient':c} for s,c in reactants],'products':[{'id':s,'coefficient':c} for s,c in products],'condition':'ambient' if activation==['none'] else 'activation','conditionLabel':label,'requiredActivation':activation,'process':'chemical','outcome':'reaction','effects':effects,'observations':observations,'explanation':explanation,'sourceIds':source_ids,'reviewStatus':'source-checked'}
 if equation_only:r['execution']='equation-only'
 reactions.append(r)
add('aluminium-oxygen-combustion','Aluminum burns to form aluminum oxide',[(Al,4),(O,3)],[(oxide,2)],['heat','ignition'],'Strong heating or ignition of aluminium with the explicitly added O₂. The surface oxide normally hinders rapid bulk reaction; this is the combustion example, not ordinary room-temperature bulk burning.',[ttu,we],['heat','flame','solid'],['An intense white flame accompanies the burning example.','Solid aluminium oxide is formed; no gas or steam is produced by this equation.'],'The balanced net equation is 4Al(s) + 3O₂(g) → 2Al₂O₃(s). The WebElements printed O₂(l) is independently corrected to O₂(g) using the Texas Tech gas-phase equation. Passivation and combustion are separate scenarios; the symbolic controls do not model a temperature or reaction rate.')
add('aluminium-oxygen-passivation','Aluminum develops a protective oxide film',[(Al,4),(O,3)],[(oxide,2)],['none'],'Room-condition surface oxidation of freshly exposed aluminium. A thin protective oxide film limits further reaction; this does not mean an entire piece burns or is converted.',[we,ttu],[],['A thin protective oxide layer forms on a newly exposed metal surface.','No bulk flame is assigned; most of a metal piece can remain protected underneath.'],'The net chemistry forms Al₂O₃, but the extent is limited by a passivating surface film. Ingredient presence is modeled, not amounts or complete conversion. Choose the heated combustion scenario for the bright burning example.')
add('aluminium-nitrogen','Aluminum combines with nitrogen',[(Al,2),(N,1)],[(nit,2)],['heat'],'Strong heating for direct nitridation of aluminium with the added N₂; oxide barriers and reaction progress are not quantitatively modeled.',[book,nitride],['heat','solid'],['Solid aluminium nitride is the reported product.','Thermal nitridation is exothermic once initiated.'],'The textbook heat-arrow equation is 2Al(s) + N₂(g) → 2AlN(s). The primary Materials study corroborates direct thermal nitridation and its exothermic nature. The equation isolates the nitrogen reaction rather than predicting a full air-combustion mixture.')
add('aluminium-sulfur','Aluminum combines with sulfur',[(Al,16),(S,3)],[(sulf,8)],['heat','ignition'],'Heating/initiating the aluminium–sulfur elemental combination. This energetic example remains conceptual; physical form and initiation strongly affect behavior.',[book,epa],['heat','solid','blast'],['Solid aluminium sulfide is formed.','The cited advisory reports vigorous, strongly energetic behaviour for heated aluminium powder with sulfur.'],'The textbook equation 2Al + 3S → Al₂S₃ is written here with molecular elemental sulfur S₈: 16Al + 3S₈ → 8Al₂S₃. Only the coefficients and elemental-sulfur representation change. This equation itself does not produce a gas.')
add('aluminium-carbon','Aluminum forms a carbide with carbon',[(Al,4),(C,3)],[(car,1)],['heat'],'Strong heating of aluminium and carbon in the textbook direct-combination scenario. Specific advanced synthesis methods and atmospheres are not simulated.',[book,carbide],['solid'],['Solid aluminium carbide is the reported binary product.'],'The textbook explicitly gives the heated elemental equation 4Al(s) + 3C(s) → Al₄C₃(s). The cited primary study corroborates production from aluminium and graphite under its specialized method; this teaching scenario does not claim every heated mixture yields pure carbide.')
add('aluminium-chlorine','Aluminum forms aluminum chloride',[(Al,2),(Cl,3)],[(chloride,2)],['heat'],'Heated aluminium with explicitly added chlorine gas; the textbook lists the solid chloride endpoint. Hot-product vaporization and later condensation are not separately simulated.',[book,we],['heat','solid'],['The reported cooled solid product is aluminium chloride.'],'The independently checked textbook equation uses Cl₂(g), correcting the WebElements Cl₂(l) transcription for this teaching scenario. The net equation is 2Al(s) + 3Cl₂(g) → 2AlCl₃(s); phases can differ in hotter gas-production examples.')
add('aluminium-bromine','Aluminum forms aluminum bromide',[(Al,2),(Br,3)],[(bromide,1)],['heat'],'Heated direct combination of aluminium with liquid bromine; the cited equation identifies solid Al₂Br₆ as the endpoint.',[we,book],['solid'],['Solid aluminium bromide is the reported product.'],'WebElements explicitly gives 2Al(s) + 3Br₂(l) → Al₂Br₆(s); the Grade 11 text identifies heating for aluminium–halogen combinations. The dimeric formula is retained rather than silently changed.')
add('aluminium-iodine-catalysed','Aluminum and iodine form aluminum iodide',[(Al,2),(I,3)],[(iodide,1)],['none'],'The cited RSC example requires water as an initiating catalyst and has an induction period. That catalyst condition is not represented by the current controls; equation only.',[iodine],['heat','flame','solid'],['The source reports aluminium iodide formation in a water-catalysed example.','Any purple cloud described by the source is excess iodine vapor, not a gaseous product in this equation.'],'The source explicitly gives 2Al(s) + 3I₂(s) → Al₂I₆(s). Water catalysis is essential to this sourced example and must not be silently replaced by the None control. Its equation is shown but is not playable until that condition can be represented.',True)
add('aluminium-fluorine','Aluminum forms aluminum fluoride',[(Al,2),(F,3)],[(fluoride,2)],['none'],'Direct elemental combination and solid AlF₃ are stated by the OCR source; complete activation and surface conditions are not supplied. Equation only.',[fluorine],['solid'],['Solid aluminium fluoride is identified by the source.'],'The official examination source states direct combination of aluminium with fluorine and a solid fluoride lattice. The balanced factual equation is 2Al(s) + 3F₂(g) → 2AlF₃(s). It does not justify a universal ambient reaction-rate prediction.',True)
handbook=source('group13-patnaik','Pradyot Patnaik, Handbook of Inorganic Chemicals: Al pp.3–4; In pp.392–394','https://enky-afina.ru/f/10a7_handbook_of_inorganic_chemicals_pradyot_patnaik_phd.pdf','2003')
P=species('P','s','Elemental phosphorus (source allotrope unspecified)');Se=species('Se','s','Elemental selenium (source allotrope unspecified)');alP=species('AlP','s','Aluminum phosphide');alSe=species('Al2Se3','s','Aluminum selenide')
add('aluminium-phosphorus-reported','Aluminum and phosphorus form aluminum phosphide',[(Al,1),(P,1)],[(alP,1)],['heat'],'The handbook reports heated aluminium powder with elemental phosphorus producing AlP, but does not specify the phosphorus allotrope or full product-selection conditions. Equation only.',[handbook],['solid'],['Aluminium phosphide is the reported binary endpoint.'],'The source explicitly names direct elemental formation of AlP. Phosphorus is retained as the source’s unspecified solid element notation, rather than silently choosing white P₄. No animation is assigned to that incomplete form specification.',True)
add('aluminium-selenium-reported','Aluminum and selenium form aluminum selenide',[(Al,2),(Se,3)],[(alSe,1)],['heat'],'The handbook reports heated aluminium powder with selenium producing Al₂Se₃; selenium allotrope and complete preparation conditions are not supplied. Equation only.',[handbook],['solid'],['Aluminium selenide is the reported binary endpoint.'],'The source gives aluminium and selenium forming Al₂Se₃. Its unspecified solid selenium is retained as Se(s), not silently changed to a molecular Se₈ allotrope. Complete form-specific kinetics are not assigned.',True)
In=species('In','s','Indium');indiumoxide=species('In2O3','s','Indium(III) oxide')
add('indium-oxygen-audited','Indium forms indium oxide',[(In,4),(O,3)],[(indiumoxide,2)],['heat'],'Heating indium in air or with the explicitly added oxygen gives the trioxide; the source reports little room-temperature air reaction.',[handbook],['solid'],['Solid indium(III) oxide is the reported heated oxidation product.'],'The handbook explicitly gives 4In + 3O₂ → 2In₂O₃ and describes the trioxide as a powder. Only qualitative heating is modeled; no rate or complete-conversion claim is made.')
gaprimary=source('group13-ga-primary','Experimental gallium study: reported Ga/O₂ oxidation equation','https://pmc.ncbi.nlm.nih.gov/articles/PMC13208902/','2026')
